scripts.original_source:
if wantenter('WATER FIELD') then begin
              with party do begin
                 map := 10; xaxis := 26; yaxis := 8;
              end;
              load;
              if party.etc[38] and bit4 > 0 then map[40,56] := 44;
           end

begin
              Clear;
              if y = 36 then
              if wantexit then begin
                 with party do begin
                    xaxis := 44; yaxis := 8; map := 2;
                 end;
                 load; scroll(TRUE);
              end
              else begin
                 dec(y); scroll(TRUE);
              end;
              if y = 10 then
              if party.etc[37] < 3 then begin
                 s := '';
                 case party.etc[37] of
                    2 : s := '한';
                    1 : s := '두';
                    0 : s := '세';
                 end;
                 Print(11,'당신은 '+s+'마리의 Wivern과 마주쳤다.');
                 PressAnyKey;
                 enemynumber := 3 - party.etc[37];
                 for i := 1 to enemynumber do joinenemy(i,43);
                 Displayenemies(TRUE);
                 BattleMode(FALSE);
                 if party.etc[6] = 255 then exit;
                 if party.etc[6] = 0 then party.etc[37] := 3
                 else begin
                    j := 0;
                    for i := 1 to enemynumber do if not enemy[i].dead then inc(j);
                    party.etc[37] := 3 - j;
                 end;
                 Clear;
              end
              else message(15,'여기에는 Wivern의 시체만이 있다.');
           end
